// ═══════════════════════════════════════════════════════════════════════════════
// Cutscenes with player 3, for the game's GOB files (Executable Tuning → Three Players).
//
// ThreePlayerCutsceneData.cs (generated by make_cutscene_data.py) holds the cutscenes Pete gave player 3: for each,
// the game's own bytes and the version with a cast member called Player3, who appears in three-player games
// (ADRIANNA23 or later). The Three Players tab puts these in the game's GOB files when you save with three players on.
// Only those cutscene entries change, and only where a GOB still has the game's own cutscene: one changed in any other
// way is left as it is. The game's own can be put back the same way.
//
// A GOB file is rebuilt the way WorldExplorer saves GOB files (GobWriter: in place when the sizes allow, otherwise
// packed), checked (every other entry byte for byte as it was), written next to itself and only then put in place.
// ═══════════════════════════════════════════════════════════════════════════════
using System.Security.Cryptography;
using System.Text;
using JetBlackEngineLib.Data.DataContainers;

namespace JetBlackEngineLib.Data.CutScenes;

/// <summary>A cutscene the Three Players tab can give player 3: where it is, the game's own bytes and the new ones.</summary>
public sealed class ThreePlayerCutscene
{
    internal ThreePlayerCutscene(string gob, string archive, string entry, byte[] original, byte[] withPlayer3)
    {
        Gob = gob;
        Archive = archive;
        Entry = entry;
        Original = original;
        WithPlayer3 = withPlayer3;
        NeedsAdrianna26 = EditableCutscene.TryLoad(withPlayer3, out var scene, out _) &&
                          scene.Keyframes.Any(k => scene.TargetWarning(k) != null);
    }

    /// <summary>The GOB file, e.g. "CUTTOWN.GOB".</summary>
    public string Gob { get; }

    /// <summary>The archive inside it, e.g. "cuttown.lmp".</summary>
    public string Archive { get; }

    /// <summary>The cutscene, e.g. "intro.cut".</summary>
    public string Entry { get; }

    internal byte[] Original { get; }
    internal byte[] WithPlayer3 { get; }

    /// <summary>A copy of the game's own cutscene.</summary>
    public byte[] GetOriginal() => (byte[])Original.Clone();

    /// <summary>A copy of the version with player 3.</summary>
    public byte[] GetWithPlayer3() => (byte[])WithPlayer3.Clone();

    /// <summary>
    /// True when the version with player 3 aims a "Face" or a camera "Look at" at Player2 or Player3. Without that
    /// player only ADRIANNA26 and later play it safely (see <see cref="EditableCutscene.TargetWarning"/>).
    /// </summary>
    public bool NeedsAdrianna26 { get; }

    public override string ToString() => $"{Entry} ({Gob})";
}

/// <summary>What a cutscene is in the game's files.</summary>
public enum ThreePlayerCutsceneState
{
    /// <summary>The game's own cutscene.</summary>
    Original,

    /// <summary>The version with player 3.</summary>
    WithPlayer3,

    /// <summary>Changed in some other way: it is left as it is.</summary>
    Changed,

    /// <summary>The GOB file, its archive or the cutscene isn't there (or the file can't be read).</summary>
    NotFound
}

/// <summary>One cutscene in the game's files: what it is, and the GOB file it is in (null when none was found).</summary>
public sealed record ThreePlayerCutsceneStatus(ThreePlayerCutscene Cutscene, ThreePlayerCutsceneState State, string? Path);

/// <summary>What <see cref="ThreePlayerCutscenes.Apply"/> did.</summary>
public sealed class ThreePlayerCutsceneResult
{
    internal ThreePlayerCutsceneResult(bool withPlayer3) => WithPlayer3 = withPlayer3;

    /// <summary>True when player 3 was being put in; false when the game's own cutscenes were being put back.</summary>
    public bool WithPlayer3 { get; }

    /// <summary>The cutscenes changed (as they were before).</summary>
    public List<ThreePlayerCutsceneStatus> Changed { get; } = new();

    /// <summary>The cutscenes that were already as wanted.</summary>
    public List<ThreePlayerCutsceneStatus> AlreadyDone { get; } = new();

    /// <summary>The cutscenes left as they are because they had been changed in some other way.</summary>
    public List<ThreePlayerCutsceneStatus> LeftAsTheyAre { get; } = new();

    /// <summary>The cutscenes whose GOB file, archive or entry wasn't found.</summary>
    public List<ThreePlayerCutsceneStatus> NotFound { get; } = new();

    /// <summary>GOB files that couldn't be updated, with the reason. Nothing in them was changed.</summary>
    public List<(string Path, string Error)> Failed { get; } = new();

    /// <summary>A few sentences for the message shown after saving.</summary>
    public string Describe()
    {
        var text = new StringBuilder();
        if (Changed.Count > 0)
        {
            text.Append(WithPlayer3 ? "Player 3 is now in " : "The game's own cutscenes are back in ")
                .Append(ThreePlayerCutscenes.CountText(Changed)).Append(": ")
                .Append(ThreePlayerCutscenes.GobList(Changed)).Append(ThreePlayerCutscenes.FolderText(Changed)).Append('.');
            if (AlreadyDone.Count > 0)
            {
                text.Append(WithPlayer3 ? " Already with player 3: " : " Already the game's own: ")
                    .Append(ThreePlayerCutscenes.CutsceneList(AlreadyDone)).Append('.');
            }
        }
        else if (AlreadyDone.Count > 0)
        {
            text.Append(WithPlayer3 ? "The cutscenes already had player 3: " : "The cutscenes were already the game's own: ")
                .Append(ThreePlayerCutscenes.CountText(AlreadyDone)).Append(ThreePlayerCutscenes.FolderText(AlreadyDone)).Append('.');
        }
        else if (Failed.Count == 0 && LeftAsTheyAre.Count == 0)
        {
            if (NotFound.All(s => s.Path == null)) return "The game's GOB files weren't found, so no cutscenes changed.";
            text.Append("No cutscene changed.");
        }

        if (LeftAsTheyAre.Count > 0)
            text.Append(" Left as they are, because they have been changed: ").Append(ThreePlayerCutscenes.CutsceneList(LeftAsTheyAre)).Append('.');
        if (NotFound.Count > 0) text.Append(' ').Append(ThreePlayerCutscenes.NotFoundText(NotFound));
        foreach (var (path, error) in Failed)
            text.Append($" {System.IO.Path.GetFileName(path)} couldn't be updated and is unchanged: {error}");
        return text.ToString().Trim();
    }
}

/// <summary>The cutscenes with player 3 and how they are put in (or taken out of) the game's GOB files.</summary>
public static class ThreePlayerCutscenes
{
    private static readonly Lazy<IReadOnlyList<ThreePlayerCutscene>> Data = new(Load);

    /// <summary>Every cutscene, in GOB file order.</summary>
    public static IReadOnlyList<ThreePlayerCutscene> All => Data.Value;

    /// <summary>The GOB files they are in, e.g. "CUTTOWN.GOB".</summary>
    public static IReadOnlyList<string> GobNames => All.Select(c => c.Gob).Distinct(StringComparer.OrdinalIgnoreCase).ToList();

    private static IReadOnlyList<ThreePlayerCutscene> Load()
    {
        var blob = Convert.FromBase64String(ThreePlayerCutsceneData.BlobBase64);
        if (Convert.ToHexString(SHA256.HashData(blob)).ToLowerInvariant() != ThreePlayerCutsceneData.BlobSha256)
            throw new InvalidDataException("The three-player cutscene data is damaged (its SHA-256 doesn't match).");
        if (Encoding.ASCII.GetString(blob, 0, 4) != "3PC1")
            throw new InvalidDataException("The three-player cutscene data has an unknown format.");

        var at = 4;
        string Text()
        {
            var length = blob[at];
            var text = Encoding.ASCII.GetString(blob, at + 1, length);
            at += 1 + length;
            return text;
        }

        byte[] Bytes()
        {
            var length = BitConverter.ToInt32(blob, at);
            var bytes = blob.AsSpan(at + 4, length).ToArray();
            at += 4 + length;
            return bytes;
        }

        var count = BitConverter.ToInt32(blob, at);
        at += 4;
        var list = new List<ThreePlayerCutscene>(count);
        for (var i = 0; i < count; i++)
        {
            var gob = Text();
            var archive = Text();
            var entry = Text();
            list.Add(new ThreePlayerCutscene(gob, archive, entry, Bytes(), Bytes()));
        }

        if (at != blob.Length) throw new InvalidDataException("The three-player cutscene data has bytes left over.");
        return list;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Looking
    // ─────────────────────────────────────────────────────────────────────────

    /// <summary>
    /// Finds each cutscene in the game's GOB files and says what it is. <paramref name="findGob"/> gives the path of a
    /// GOB file by its name ("CUTTOWN.GOB"), or null when there is none.
    /// </summary>
    public static List<ThreePlayerCutsceneStatus> Inspect(Func<string, string?> findGob)
    {
        var result = new List<ThreePlayerCutsceneStatus>();
        foreach (var group in All.GroupBy(c => c.Gob, StringComparer.OrdinalIgnoreCase))
        {
            var path = findGob(group.Key);
            List<ThreePlayerCutsceneState>? states = null;
            if (path != null)
            {
                try
                {
                    var gob = Open(group.Key, File.ReadAllBytes(path));
                    states = group.Select(c => StateIn(gob, c)).ToList();
                }
                catch (Exception ex) when (IsFileProblem(ex))
                {
                    states = null; // can't be read: as good as not there
                }
            }

            var i = 0;
            foreach (var cutscene in group)
            {
                result.Add(new ThreePlayerCutsceneStatus(cutscene, states?[i] ?? ThreePlayerCutsceneState.NotFound, path));
                i++;
            }
        }

        return result;
    }

    /// <summary>What <paramref name="cutscene"/> is in <paramref name="gob"/>.</summary>
    private static ThreePlayerCutsceneState StateIn(GobFile gob, ThreePlayerCutscene cutscene)
    {
        var bytes = EntryBytes(gob, cutscene);
        if (bytes == null) return ThreePlayerCutsceneState.NotFound;
        if (bytes.AsSpan().SequenceEqual(cutscene.Original)) return ThreePlayerCutsceneState.Original;
        if (bytes.AsSpan().SequenceEqual(cutscene.WithPlayer3)) return ThreePlayerCutsceneState.WithPlayer3;
        return ThreePlayerCutsceneState.Changed;
    }

    private static GobFile Open(string name, byte[] bytes)
    {
        var gob = new GobFile(EngineVersion.DarkAlliance, name, bytes);
        foreach (var lmp in gob.Directory.Values) lmp.EnsureDirectory();
        return gob;
    }

    private static LmpFile? FindArchive(GobFile gob, string archive) =>
        gob.Directory.TryGetValue(archive, out var lmp)
            ? lmp
            : gob.Directory.FirstOrDefault(p => string.Equals(p.Key, archive, StringComparison.OrdinalIgnoreCase)).Value;

    private static byte[]? EntryBytes(GobFile gob, ThreePlayerCutscene cutscene)
    {
        var lmp = FindArchive(gob, cutscene.Archive);
        return lmp?.FindDirectoryName(cutscene.Entry) is { } entry ? lmp.GetEntryBytes(entry) : null;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Changing
    // ─────────────────────────────────────────────────────────────────────────

    /// <summary>
    /// The bytes of a GOB file with each of its cutscenes given player 3 (<paramref name="withPlayer3"/>) or put back
    /// to the game's own, where the GOB has the other version; null when nothing changes. Every other entry is kept
    /// byte for byte, which is checked. <paramref name="found"/>, when given, receives what each cutscene was.
    /// </summary>
    public static byte[]? Update(string gobName, byte[] gob, bool withPlayer3, List<ThreePlayerCutsceneStatus>? found = null)
    {
        var file = Open(gobName, gob);
        var from = withPlayer3 ? ThreePlayerCutsceneState.Original : ThreePlayerCutsceneState.WithPlayer3;
        var changed = new List<ThreePlayerCutscene>();
        foreach (var cutscene in All.Where(c => string.Equals(c.Gob, gobName, StringComparison.OrdinalIgnoreCase)))
        {
            var state = StateIn(file, cutscene);
            found?.Add(new ThreePlayerCutsceneStatus(cutscene, state, null));
            if (state != from) continue;
            var lmp = FindArchive(file, cutscene.Archive)!;
            lmp.ReplaceEntry(lmp.FindDirectoryName(cutscene.Entry)!, withPlayer3 ? cutscene.WithPlayer3 : cutscene.Original);
            changed.Add(cutscene);
        }

        if (changed.Count == 0) return null;
        var bytes = GobWriter.TryPatchInPlace(file) ?? GobWriter.Pack(file);
        CheckUpdate(gobName, gob, bytes, changed, withPlayer3);
        return bytes;
    }

    /// <summary>
    /// Checks a rebuilt GOB against the one it was made from: the same archives and entries in the same order, the
    /// changed cutscenes as wanted and every other entry byte for byte as it was.
    /// </summary>
    private static void CheckUpdate(string gobName, byte[] before, byte[] after, List<ThreePlayerCutscene> changed, bool withPlayer3)
    {
        var a = Open(gobName, before);
        var b = Open(gobName, after);
        if (!a.Directory.Keys.SequenceEqual(b.Directory.Keys))
            throw new InvalidDataException($"{gobName} came out with different archives.");
        foreach (var (name, lmpA) in a.Directory)
        {
            var lmpB = b.Directory[name];
            if (!lmpA.Directory.Keys.SequenceEqual(lmpB.Directory.Keys))
                throw new InvalidDataException($"{gobName} {name} came out with different entries.");
            foreach (var entry in lmpA.Directory.Keys)
            {
                var cutscene = changed.FirstOrDefault(c => string.Equals(c.Archive, name, StringComparison.OrdinalIgnoreCase) &&
                                                           string.Equals(c.Entry, entry, StringComparison.OrdinalIgnoreCase));
                var want = cutscene == null ? lmpA.GetEntryBytes(entry)! : withPlayer3 ? cutscene.WithPlayer3 : cutscene.Original;
                if (!lmpB.GetEntryBytes(entry)!.AsSpan().SequenceEqual(want))
                    throw new InvalidDataException($"{gobName} {name} {entry} came out different.");
            }
        }
    }

    /// <summary>
    /// Gives the cutscenes player 3 in the game's GOB files (<paramref name="withPlayer3"/>), or puts the game's own
    /// back. A GOB file that changes is rebuilt and checked (<see cref="Update"/>), written next to itself, read back
    /// and only then put in place, so a file that can't be updated stays as it was.
    /// </summary>
    public static ThreePlayerCutsceneResult Apply(Func<string, string?> findGob, bool withPlayer3)
    {
        var result = new ThreePlayerCutsceneResult(withPlayer3);
        foreach (var group in All.GroupBy(c => c.Gob, StringComparer.OrdinalIgnoreCase))
        {
            var path = findGob(group.Key);
            if (path == null)
            {
                result.NotFound.AddRange(group.Select(c => new ThreePlayerCutsceneStatus(c, ThreePlayerCutsceneState.NotFound, null)));
                continue;
            }

            var found = new List<ThreePlayerCutsceneStatus>();
            var temp = path + ".player3.tmp";
            try
            {
                var bytes = File.ReadAllBytes(path);
                var updated = Update(group.Key, bytes, withPlayer3, found);
                if (updated != null)
                {
                    File.WriteAllBytes(temp, updated);
                    if (!File.ReadAllBytes(temp).AsSpan().SequenceEqual(updated))
                        throw new IOException("the file written didn't read back the same.");
                    File.Move(temp, path, overwrite: true);
                }
            }
            catch (Exception ex) when (IsFileProblem(ex))
            {
                result.Failed.Add((path, ex.Message));
                continue;
            }
            finally
            {
                try
                {
                    if (File.Exists(temp)) File.Delete(temp);
                }
                catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
                {
                    // a leftover temporary file is harmless
                }
            }

            foreach (var status in found)
            {
                var withPath = status with { Path = path };
                switch (status.State)
                {
                    case ThreePlayerCutsceneState.Original when withPlayer3:
                    case ThreePlayerCutsceneState.WithPlayer3 when !withPlayer3:
                        result.Changed.Add(withPath);
                        break;
                    case ThreePlayerCutsceneState.Original:
                    case ThreePlayerCutsceneState.WithPlayer3:
                        result.AlreadyDone.Add(withPath);
                        break;
                    case ThreePlayerCutsceneState.Changed:
                        result.LeftAsTheyAre.Add(withPath);
                        break;
                    default:
                        result.NotFound.Add(withPath);
                        break;
                }
            }
        }

        return result;
    }

    /// <summary>
    /// Anything that goes wrong reading, rebuilding or writing one GOB file: a damaged file can fail anywhere in the
    /// readers. That file is then left as it was and reported; only running out of memory isn't caught.
    /// </summary>
    private static bool IsFileProblem(Exception ex) => ex is not OutOfMemoryException;

    // ─────────────────────────────────────────────────────────────────────────
    // Texts for the Three Players tab
    // ─────────────────────────────────────────────────────────────────────────

    /// <summary>
    /// What saving with the box ticked will do, from <see cref="Inspect"/>: e.g. "When you save, player 3 is added to
    /// 8 cutscenes in 7 GOB files: BTHRONE, CRYPT2, … (in D:\BGDA\BG\DATA)."
    /// </summary>
    public static string DescribePlan(IReadOnlyList<ThreePlayerCutsceneStatus> statuses)
    {
        var toDo = statuses.Where(s => s.State == ThreePlayerCutsceneState.Original).ToList();
        var done = statuses.Where(s => s.State == ThreePlayerCutsceneState.WithPlayer3).ToList();
        var changed = statuses.Where(s => s.State == ThreePlayerCutsceneState.Changed).ToList();
        var missing = statuses.Where(s => s.State == ThreePlayerCutsceneState.NotFound).ToList();
        if (missing.Count == statuses.Count && missing.All(s => s.Path == null))
            return $"The game's GOB files ({GobList(missing)}) weren't found, so no cutscenes will change.";

        var text = new StringBuilder();
        if (toDo.Count > 0)
        {
            text.Append("When you save, player 3 is added to ").Append(CountText(toDo)).Append(": ")
                .Append(GobList(toDo)).Append(FolderText(toDo)).Append(". Only those cutscenes change.");
            if (done.Count > 0) text.Append(" Already with player 3: ").Append(CutsceneList(done)).Append('.');
        }
        else if (done.Count > 0)
        {
            text.Append("The game's cutscenes already have player 3: ").Append(CountText(done)).Append(FolderText(done)).Append('.');
        }
        else
        {
            text.Append("No cutscene will change.");
        }

        if (changed.Count > 0)
            text.Append(" Left as they are, because they have been changed: ").Append(CutsceneList(changed)).Append('.');
        if (missing.Count > 0) text.Append(' ').Append(NotFoundText(missing));
        return text.ToString();
    }

    /// <summary>
    /// True when the game's GOB files have a cutscene with player 3 that only ADRIANNA26 and later play safely
    /// (<see cref="ThreePlayerCutscene.NeedsAdrianna26"/>), so turning three players off should offer to put the
    /// game's own cutscenes back.
    /// </summary>
    public static bool ShouldOfferPuttingBack(IReadOnlyList<ThreePlayerCutsceneStatus> statuses) =>
        statuses.Any(s => s.State == ThreePlayerCutsceneState.WithPlayer3 && s.Cutscene.NeedsAdrianna26);

    /// <summary>
    /// What turning three players off means for the cutscenes in the game's GOB files, from <see cref="Inspect"/>;
    /// null when none of them has player 3.
    /// </summary>
    public static string? DescribeTurnOff(IReadOnlyList<ThreePlayerCutsceneStatus> statuses)
    {
        var installed = statuses.Where(s => s.State == ThreePlayerCutsceneState.WithPlayer3).ToList();
        if (installed.Count == 0) return null;
        var text = $"{CountText(installed)} {(installed.Count == 1 ? "has" : "have")} player 3{FolderText(installed)}.";
        var risky = installed.Where(s => s.Cutscene.NeedsAdrianna26).ToList();
        return risky.Count == 0
            ? text + " That's harmless without three players: nobody plays player 3 in them."
            : text + $" {CutsceneList(risky)} {(risky.Count == 1 ? "has" : "have")} a Face or Look at aimed at Player3, which " +
              "only ADRIANNA26 and later play safely, so when you save you'll be asked whether to put the game's own cutscenes back.";
    }

    /// <summary>The question asked after saving with three players turned off, when <see cref="ShouldOfferPuttingBack"/>.</summary>
    public static string PuttingBackQuestion(IReadOnlyList<ThreePlayerCutsceneStatus> statuses)
    {
        var installed = statuses.Where(s => s.State == ThreePlayerCutsceneState.WithPlayer3).ToList();
        var risky = installed.Where(s => s.Cutscene.NeedsAdrianna26).ToList();
        return $"Three players are off in the executable you saved, but {CountText(installed)} in the game still " +
               $"{(installed.Count == 1 ? "has" : "have")} player 3{FolderText(installed)}.\n\n" +
               "Put the game's own cutscenes back?\n\n" +
               $"{CutsceneList(risky)} {(risky.Count == 1 ? "has" : "have")} a Face or Look at aimed at Player3. Executables " +
               "older than ADRIANNA26, the stock one too, crash on that in one- and two-player games. Choose No if the " +
               "game will still use a three-player executable.";
    }

    /// <summary>"8 cutscenes in 7 GOB files", "1 cutscene in 1 GOB file".</summary>
    internal static string CountText(IReadOnlyCollection<ThreePlayerCutsceneStatus> statuses)
    {
        var gobs = statuses.Select(s => s.Cutscene.Gob).Distinct(StringComparer.OrdinalIgnoreCase).Count();
        return $"{statuses.Count} cutscene{(statuses.Count == 1 ? "" : "s")} in {gobs} GOB file{(gobs == 1 ? "" : "s")}";
    }

    /// <summary>"BTHRONE, CRYPT2 and CUTTOWN".</summary>
    internal static string GobList(IEnumerable<ThreePlayerCutsceneStatus> statuses) =>
        Join(statuses.Select(s => Path.GetFileNameWithoutExtension(s.Cutscene.Gob)).Distinct(StringComparer.OrdinalIgnoreCase).ToList());

    /// <summary>"intro.cut (CUTTOWN.GOB) and garik.cut (BTHRONE.GOB)".</summary>
    internal static string CutsceneList(IEnumerable<ThreePlayerCutsceneStatus> statuses) =>
        Join(statuses.Select(s => s.Cutscene.ToString()).ToList());

    /// <summary>" (in D:\BGDA\BG\DATA)", or "" when no folder is known.</summary>
    internal static string FolderText(IEnumerable<ThreePlayerCutsceneStatus> statuses)
    {
        var folders = statuses.Where(s => s.Path != null).Select(s => Path.GetDirectoryName(s.Path!) ?? "")
            .Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        return folders.Count == 0 ? "" : $" (in {Join(folders)})";
    }

    /// <summary>"Not found: SEWER1.GOB and eldrithend.cut in TOWERT.GOB."</summary>
    internal static string NotFoundText(IEnumerable<ThreePlayerCutsceneStatus> statuses)
    {
        var parts = new List<string>();
        foreach (var group in statuses.GroupBy(s => s.Cutscene.Gob, StringComparer.OrdinalIgnoreCase))
        {
            var withoutFile = group.All(s => s.Path == null);
            parts.Add(withoutFile
                ? group.Key
                : $"{Join(group.Select(s => s.Cutscene.Entry).ToList())} in {group.Key}");
        }

        return $"Not found: {Join(parts)}.";
    }

    private static string Join(IReadOnlyList<string> items) => items.Count switch
    {
        0 => "",
        1 => items[0],
        _ => string.Join(", ", items.Take(items.Count - 1)) + " and " + items[^1]
    };
}
